    /**
     * Resource Type
     */
    resource_type?: number;
    /**
     * Resource Id
     */
    resource_id?: number;
    /**
     * Root Id
     */
    root_id?: number;
    /**
     * Source Id
     */
    source_id?: number;
    /**
     * Target Id
     */
    target_id?: number;
    /**
     * Title
     */
    title?: string;
    /**
     * Desc
     */
    desc?: string;
    /**
     * Image
     */
    image?: string;
    /**
     * Source Content
     */
    source_content?: string;
    /**
     * Target Content
     */
    target_content?: string;
    /**
     * Source Mid
     */
    source_mid?: number;
    /**
     * Target Mid
     */
    target_mid?: number;
    /**
     * Source Name
     */
    source_name?: string;
    /**
     * Target Name
     */
    target_name?: string;
    /**
     * Comment Deleted
     */
    comment_deleted?: boolean;
    /**
     * Jump Target
     */
    jump_target?: string;
    /**
     * Resource Deleted
     */
    resource_deleted?: boolean;
    /**
     * Ctime
     */
    ctime: number;
    /**
     * Item Id Str
     */
    readonly item_id_str: string | null;
    /**
     * Resource Id Str
     */
    readonly resource_id_str: string | null;
    /**
     * Root Id Str
     */
