/**
 * SysConfigItem
 *
 * 单个运行时配置项（管理端读）。
 *
 * `isDefault=True` 表示该 key 尚未写入 `msg_sys_config`，当前生效的是 settings 默认值
 * （管理端据此展示「默认值 / 已覆盖」状态，并可把默认值直接改为自定义值）。
 */
export type SysConfigItem = {
    /**
     * Key
     */
    key: string;
    /**
     * Value
     */
    value: {
        [key: string]: unknown;
    };
    /**
     * Remark
     */
    remark?: string | null;
    /**
     * Updatedby
     *
     * 最后修改者 mid（字符串版见 updatedBy_str）
     */
    updatedBy?: number;
    /**
     * Updated At
     *
     * 最后更新时间（秒级时间戳）
     */
    updated_at?: number | null;
    /**
     * Isdefault
     *
     * 是否仍是 settings 默认值（未写入 DB）
     */
    isDefault?: boolean;
    /**
     * Updatedby Str
     */
    readonly updatedBy_str: string | null;
};

/**
 * SysConfigListResp
 *
 * 运行时配置列表（管理端读）。
 */
export type SysConfigListResp = {
    /**
     * Items
     */
    items?: Array<SysConfigItem>;
};

/**
 * SysConfigUpdateReq
 *
 * 写入运行时配置（整体替换该 key 的值）。
 */
export type SysConfigUpdateReq = {
    /**
     * Key
     *
     * 配置键（必须是已登记的可热更新项）
     */
    key: string;
    /**
     * Value
     *
     * 配置值（JSON，整体替换；按 key 派发校验）
     */
    value: {
        [key: string]: unknown;
    };
    /**
     * Remark
     *
     * 备注
     */
    remark?: string | null;
};

/**
 * SystemNotifyItem
 *
 * 模仿 B 站 `/x/v2/feedsystem/system_notify/get` 的列表项。
 *
 * - `cursor`：发布时间（UTC）的纳秒时间戳，与 B 站一致。
 * - `content`：B 站把正文包成 `{"web": "..."}` 的 JSON 字符串。
 * - `type`：系统通知固定为 4。
 * - `is_send`：映射本服务的 `dispatched`（是否已投递推送）。
 */
export type SystemNotifyItem = {
    /**
     * Id
     */
    id: number;
    /**
     * Cursor
     */
    cursor?: number;
    /**
     * Type
     */
    type?: number;
    /**
     * Title
     */
    title: string;
    /**
     * Content
     */
    content: string;
    source?: SystemNotifySource;
    /**
     * Time At
     */
    time_at?: string;
    /**
     * Card Type
     */
    card_type?: number;
    /**
     * Card Brief
     */
    card_brief?: string;
    /**
     * Card Msg Brief
     */
    card_msg_brief?: string;
    /**
     * Card Cover
     */
    card_cover?: string;
    /**
     * Card Story Title
     */
    card_story_title?: string;
    /**
     * Card Link
     */
    card_link?: string;
    /**
     * Mc
     */
    mc?: string;
    /**
     * Is Station
     */
    is_station?: number;
    /**
     * Is Send
     */
    is_send?: number;
    /**
     * Notify Cursor
     */
    notify_cursor?: number;
};

